import type { Permission, UserMePublic } from "@/client"
import { currentUserQueryOptions } from "@/hooks/useAuth"

/**
 * The one place where the frontend decides what the current user may do.
 *
 * The permissions arrive from the backend with the current user, so the rules
 * for which role may do what exist only in the backend policy.
 */
export const hasPermission = (
  user: UserMePublic | null | undefined,
  permission: Permission,
): boolean => user?.permissions.includes(permission) ?? false

/** Thrown by a route guard. Guarded routes render it as the Forbidden page. */
export class ForbiddenError extends Error {}

// A guard may reuse an answer this recent. Older than that, or after a 403
// has invalidated it, the guard asks the backend again.
const GUARD_STALE_TIME_MS = 10_000

/**
 * Route guard for `beforeLoad`: lets the navigation through only if the
 * current user has the permission. It runs before the page renders, so a
 * refused user never sees the page and its data is never requested.
 */
export const requirePermission = async (
  queryClient: QueryClient,
  permission: Permission,
): Promise<void> => {
  const user = await queryClient.query({
    ...currentUserQueryOptions,
    staleTime: GUARD_STALE_TIME_MS,
  })
  if (!hasPermission(user, permission)) {
    throw new ForbiddenError()
  }
}
''')

