// A 403 means the user's access is not what this page assumed, typically
// because their role changed while they had it open. Ask the backend once who
// they are now. Route guards re-run only if the answer differs, so a request
// that stays forbidden cannot start a loop. The refused request is not retried.
const refreshAccess = async () => {
  const { queryKey } = currentUserQueryOptions
  const before = queryClient.getQueryData(queryKey)
  const after = await queryClient
